('pkg1a065fe71a3i1tqbu', 'sv1a065fe71a3t8zk1k', 'BM', '', 'BM004', 'BM004', 'BM004A', 'Electrical contact burns: Low voltage - without part of limb / limb loss; Includes % TBSA skin grafted, flap cover, follow- up dressings etc. as deemed necessary; Surgical procedures are required for deep burns that are not amenable to heal with dressings alone.', 45000, 'Tier1 (X)', 0, '', '', ''),
